45:
46:    private static final boolean DBG = Slogf.isLoggable(TAG, Log.DEBUG);
47:
48:    private final DeathRecipient mDeathRecipient;
49:
50:    public final int uid;
51:    public final String packageName;
52:    public final ICarResultReceiver receiver;
53:    /**
54:     * List of filters that are associcated with the listeners of this receiver.
55:     * A null list means that the filters always pass thus the receiver is called for all events.
56:     */
57:    private @Nullable ArrayList<UserLifecycleEventFilter> mFilters;
58:
59:    AppLifecycleListener(int uid, String packageName, ICarResultReceiver receiver,
60:            @Nullable UserLifecycleEventFilter filter, BinderDeathCallback binderDeathCallback) {
61:        this.uid = uid;
62:        this.packageName = packageName;
63:        this.receiver = receiver;
64:        if (filter != null) {
65:            if (DBG) {
66:                Slogf.d(TAG, "AppLifecycleListener: filter list for receiver %s of package %s"
67:                        + " is initialized with filter %s.", receiver, packageName, filter);
68:            }
69:            mFilters = new ArrayList<>(1);
70:            mFilters.add(filter);
71:        }
72:
73:        mDeathRecipient = () -> binderDeathCallback.onBinderDeath(this);
74:        Slogf.v(TAG, "linking death recipient %s", mDeathRecipient);
75:        try {
76:            receiver.asBinder().linkToDeath(mDeathRecipient, /* flags= */ 0);
77:        } catch (RemoteException e) {
78:            Slogf.wtf(TAG, "Cannot listen to death of %s", mDeathRecipient);
79:        }
80:    }
81:
82:    @VisibleForTesting
83:    @Nullable List<UserLifecycleEventFilter> getFilters() {
84:        return mFilters;
85:    }
86:
87:    void addFilter(@Nullable UserLifecycleEventFilter filter) {
88:        // There has been a null filter added. Ignore any other filters.
89:        if (mFilters == null) {
90:            if (DBG) {
91:                Slogf.d(TAG, "addFilter: filter %s is ignored for receiver %s since it already has"
92:                        + " a null filter added before.", filter, this);
93:            }
94:            return;
95:        }
96:        if (filter == null) {
97:            if (DBG) {
98:                Slogf.d(TAG, "addFilter: Setting the filter list to null for receiver %s due to"
99:                        + " adding a null filter.", this);
100:            }
101:            // Adding a null filter will set the list to null, making all events pass.
102:            mFilters = null;
103:        } else {
104:            if (DBG) {
105:                Slogf.d(TAG, "addFilter: Adding a new filter %s to the filter list of receiver %s",
106:                        filter, this);
107:            }
108:            mFilters.add(filter);
109:        }
110:    }
111:
112:    boolean applyFilters(UserLifecycleEvent event) {
113:        // Always return true when the list is null.
114:        if (mFilters == null) {
115:            if (DBG) {
116:                Slogf.d(TAG, "applyFilters: returns true for event %s since the filter list is null"
117:                        + " for receiver %s.", event, this);
118:            }
119:            return true;
120:        }
121:
122:        // Only non-null filters. Returns true when any of the filters passes the event.
123:        for (int i = 0; i < mFilters.size(); i++) {
124:            // If any of the filters passes the event, then return true.
125:            UserLifecycleEventFilter filter = mFilters.get(i);
126:            if (filter.apply(event)) {
127:                if (DBG) {
128:                    Slogf.d(TAG, "applyFilters: returns true for event %s since the filter %s"
129:                            + " evaluates to true for receiver %s.", event, filter, this);
130:                }
131:                return true;
132:            }
133:        }
134:
135:        if (DBG) {
136:            Slogf.d(TAG, "applyFilters: returns false for event %s since all filters in the list"
137:                    + " evaluates to false for receiver %s.", event, this);
138:        }
139:        return false;
140:    }
