142:    void onDestroy() {
143:        Slogf.v(TAG, "onDestroy(): unlinking death recipient %s", mDeathRecipient);
144:        receiver.asBinder().unlinkToDeath(mDeathRecipient, /* flags= */ 0);
145:    }
